		if (!modal) {
			return;
		}
		const topicEl = $(this).parents('[component="category/topic"]');
		const isSelected = topicEl.hasClass('selected');
		const tid = topicEl.attr('data-tid');
		if (isSelected) {
			Merge.addTopic(tid);
		} else {
			Merge.removeTopic(tid);
